solution.solution.cpp:
#include <cctype>
#include <optional>
#include <string>

struct DeviceNames { std::string device, link, user; };

std::optional<DeviceNames> deviceNames(const std::string& base)
{
    if (base.empty() || base.size() > 32) return std::nullopt;
    for (char c : base)
        if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_') return std::nullopt;
    return DeviceNames{ "\\Device\\" + base, "\\??\\" + base, "\\\\.\\" + base };
}

unsigned byteLength(const std::string& text)
{
    return static_cast<unsigned>(text.size() * 2);      // two bytes per UTF-16 unit, no terminator
}

unitTests:
TEST("the three names")
{
    const auto n{ deviceNames("XenonEcho") };
    CHECK(n.has_value());
    CHECK_EQ(n->device, std::string("\\Device\\XenonEcho"));
    CHECK_EQ(n->link, std::string("\\??\\XenonEcho"));
    CHECK_EQ(n->user, std::string("\\\\.\\XenonEcho"));
}
TEST("underscores and digits") { CHECK(deviceNames("Echo_2").has_value()); }
TEST("bad names") { CHECK(!deviceNames("").has_value()); CHECK(!deviceNames("Xenon Echo").has_value()); CHECK(!deviceNames("a\\b").has_value()); CHECK(!deviceNames(std::string(33, 'x')).has_value()); }
TEST("unicode string length") { CHECK_EQ(byteLength("\\Device\\XenonEcho"), 34u); CHECK_EQ(byteLength(""), 0u); }

